{
  "decline_reason": "",
  "claims": [
    {
      "text": "Lack of knowledge matters: section 121(4)(a) provides that the trade mark is not infringed if the owner acquired the goods both in good faith and without being aware of the prohibition notice; lack of awareness alone is not the full condition.",
      "quotes": [
        {
          "ref": "TMA1995/s121",
          "quote": "(4) The trade mark is not infringed if the owner of the goods: (a) acquired them in good faith and without being aware of the notice of prohibition;"
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "Section 121 concerns a notice displayed by the registered owner, or an authorised user with power to do so, on registered goods, their packaging or their container, prohibiting an act specified in subsection (2).",
      "quotes": [
        {
          "ref": "TMA1995/s121",
          "quote": "(1) This section applies to a registered trade mark if the registered owner, or an authorised user of the trade mark having power to do so, has caused to be displayed on goods (registered goods) in respect of which the trade mark is registered, or on their package, or on the container in which they are offered to the public, a notice (notice of prohibition) prohibiting any act that is under subsection (2) a prohibited act in relation to the goods."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "Buying the goods is not itself the infringement described in section 121(3): subject to subsection (4), the owner must do or authorise an act prohibited by the notice, in the course of trade or with a view to a dealing with the goods in the course of trade.",
      "quotes": [
        {
          "ref": "TMA1995/s121",
          "quote": "(3) Subject to subsection (4), a person infringes a trade mark to which this section applies if the person: (a) is the owner of registered goods; and (b) in the course of trade, or with a view to a dealing with the goods in the course of trade: (i) does an act that is prohibited under the notice of prohibition; or (ii) authorises that act to be done."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The exception also covers an owner whose title derives from someone who acquired the goods in good faith and without awareness of the notice.",
      "quotes": [
        {
          "ref": "TMA1995/s121",
          "quote": "(4) The trade mark is not infringed if the owner of the goods: (a) acquired them in good faith and without being aware of the notice of prohibition; or (b) became the owner of the goods by virtue of a title derived from a person who had so acquired them."
        }
      ],
      "authority": "legislation"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0072",
    "GC-0088",
    "GC-0084",
    "GC-0083"
  ]
}
